// Configuration lives here, not in the payload. The callback always goes to API_BASE_URL.
const API_BASE_URL = 'https://api.example.com'; // ← your Silent Handover API
const MODEL = 'REPLACE_WITH_CURRENT_MODEL'; // ← e.g. your provider's current JSON-schema-capable model

const body = $input.first().json.body;
for (const key of ['event_id', 'attempt', 'report_id', 'prompt_version', 'system_prompt', 'user_prompt', 'response_schema']) {
  if (body[key] === undefined) throw new Error(`Missing ${key}`);
}
return [{ json: {
  event_id: body.event_id,
  attempt: body.attempt,
  report_id: body.report_id,
  prompt_version: body.prompt_version,
  system_prompt: body.system_prompt,
  user_prompt: body.user_prompt,
  response_schema: body.response_schema,
  model: MODEL,
  callback_url: `${API_BASE_URL}/api/integrations/n8n/analysis-result`,
  started_at: Date.now(),
} }];

// Pass the raw model text back unchanged. The API validates it against the schema;
// n8n does not decide whether the output is acceptable.
const prep = $('Prepare').first().json;
const res = $input.first().json;
const message = res.choices?.[0]?.message ?? {};
if (message.refusal || !message.content) {
  return [{ json: { event_id: prep.event_id, attempt: prep.attempt, status: 'error', error: message.refusal ? `Model refused: ${String(message.refusal).slice(0, 300)}` : 'Empty model response', model: res.model ?? prep.model, latency_ms: Date.now() - prep.started_at } }];
}
return [{ json: {
  event_id: prep.event_id,
  attempt: prep.attempt,
  status: 'ok',
  output: message.content,
  model: res.model ?? prep.model,
  usage: res.usage ?? {},
  latency_ms: Date.now() - prep.started_at,
} }];

const prep = $('Prepare').first().json;
const err = $input.first().json.error ?? $input.first().json;
const message = typeof err === 'string' ? err : (err.message ?? JSON.stringify(err)).slice(0, 500);
return [{ json: { event_id: prep.event_id, attempt: prep.attempt, status: 'error', error: message, model: prep.model, latency_ms: Date.now() - prep.started_at } }];
